// 解析JSON字符串，兼容Webhook和Lark Trigger两种输入
let questionContent = $json.question;

// 如果question为null或undefined，尝试从PrimaryParam获取
if (!questionContent) {
  try {
    questionContent = $('PrimaryParam').item.json.question;
  } catch (e) {
    // 如果还是获取不到，尝试从Webhook的body获取
    questionContent = $json.body?.message?.content || $json.message?.content;
  }
}

// 如果questionContent是字符串，尝试解析JSON
let questionData;
if (typeof questionContent === 'string') {
  try {
    questionData = JSON.parse(questionContent);
  } catch (e) {
    // 如果不是JSON格式，直接使用字符串
    questionData = { text: questionContent };
  }
} else if (questionContent && typeof questionContent === 'object') {
  // 如果已经是对象，直接使用
  questionData = questionContent;
} else {
  // 默认值
  questionData = { text: '' };
}

// 提取text内容
return {
  json: {
    original_question: questionContent,
    extracted_text: questionData.text || questionData.content || ''
  }
};

// 获取原始文本 - 添加空值保护
let originalText = $('AskRAG').item.json.data?.answer || '知识库中未找到您要的答案！';
const mdText = $json.markdown || '';

// JSON安全转义函数 - 增强版
const jsonEscape = (str) => {
  if (!str) return '';
  return str
    .replace(/\\/g, '\\\\')    // 反斜杠
    .replace(/"/g, '\\"')      // 双引号
    .replace(/\n/g, '\\n')     // 换行符
    .replace(/\r/g, '\\r')     // 回车符
    .replace(/\t/g, '\\t')     // 制表符
    .replace(/\f/g, '\\f')     // 换页符
    .replace(/\v/g, '\\v')     // 垂直制表符
    .replace(/[\x00-\x1F\x7F]/g, ''); // 移除其他控制字符
};

const escapedText = jsonEscape(originalText);
// 如果没有 references，显示占位文本而不是空字符串
const escapedMdText = mdText ? jsonEscape(mdText) : '(无相关文档引用)';

return {
  json: {
    original_text: originalText,
    escaped_text: escapedText,
    escapedMdText: escapedMdText
  }
};

// 获取原始文本
const originalText = $json.extracted_text;

// JSON安全转义函数
const jsonEscape = (str) => {
  return str
    .replace(/\\/g, '\\\\')    // 反斜杠
    .replace(/"/g, '\\"')      // 双引号
    .replace(/\n/g, '')     // 换行符
    .replace(/\r/g, '\\r')     // 回车符
    .replace(/\t/g, '\\t')     // 制表符
    .replace(/\f/g, '\\f')     // 换页符
    .replace(/\v/g, '\\v');    // 垂直制表符
};

const escapedText = jsonEscape(originalText);

return {
  json: {
    original_text: originalText,
    escaped_text: escapedText
  }
};

// 获取输入的 JSON 数据
const ragData = $('AskRAG').first().json.data;
const inputData = ragData?.reference;

// 检查是否有有效的 reference 和 chunks
if (!inputData || !inputData.chunks || inputData.chunks.length === 0) {
  // 返回空占位符，避免后续节点崩溃
  return [{ json: { index: 0, document_id: '', dataset_id: '', document_name: '', image_id: '' } }];
}

const chunks = inputData.chunks;

// 提取每个 chunk 的 4 个字段
const results = chunks.map((chunk, index) => {
  return {
    json: {
      index: index,
      document_id: chunk.document_id || '',
      dataset_id: chunk.dataset_id || '',
      document_name: chunk.document_name || '',
      image_id: chunk.image_id || ''
    }
  };
});

return results;

// 确保只处理第一个 item，或收集所有输入后合并
const allItems = $input.all();
const firstItem = allItems[0].json;
const chunk = firstItem.chunk ?? firstItem; // 兼容不同输入结构

const base = 'http://10.1.9.133:8080/chunk/parsed/chunks';

let mdLines = ['References'];
let elements = [];

// 检查是否有有效的 document_id 数组
const docIds = chunk.document_id;
if (!docIds || (Array.isArray(docIds) && docIds.length === 0) || docIds === '') {
  // 没有有效的 references，返回空
  return [{ json: { markdown: '', card: null } }];
}

// 处理单个文档ID的情况（非数组）
const docIdArray = Array.isArray(docIds) ? docIds : [docIds];
const datasetIdArray = Array.isArray(chunk.dataset_id) ? chunk.dataset_id : [chunk.dataset_id];
const docNameArray = Array.isArray(chunk.document_name) ? chunk.document_name : [chunk.document_name];

for (let i = 0; i < docIdArray.length; i++) {
  const name = docNameArray[i] || 'Unknown';
  const docId = docIdArray[i];
  const url = `${base}?id=${datasetIdArray[i]}&doc_id=${docId}`;

  if (docId && docId !== '') {
    mdLines.push(`- [${name}](${url})`);
    elements.push({
      tag: 'div',
      text: { tag: 'lark_md', content: `[${name}](${url})` },
    });
  }
}

const markdown = mdLines.length > 1 ? mdLines.join('\n') : '';
const card = elements.length > 0 ? {
  config: { wide_screen_mode: true, enable_forward: false },
  header: {
    title: { tag: 'plain_text', content: 'Chunk References' },
    template: 'blue',
  },
  elements,
} : null;

return [{ json: { markdown, card } }];

// 解析OpenRouter返回的结果
// 从EscapedCharacters1获取原始问题
const originalQuestion = $('EscapedCharacters1').item.json.escaped_text;

// 获取LLM返回的增强问题
let enhancedQuestion = '';
try {
  enhancedQuestion = $json.choices?.[0]?.message?.content || '';
  enhancedQuestion = enhancedQuestion.trim();
} catch (e) {
  console.log('解析LLM返回失败:', e.message);
  enhancedQuestion = originalQuestion; // 失败时使用原问题
}

// 如果LLM返回为空，使用原问题
if (!enhancedQuestion) {
  enhancedQuestion = originalQuestion;
}

// JSON安全转义
const jsonEscape = (str) => {
  return str
    .replace(/\\/g, '\\\\')
    .replace(/"/g, '\\"')
    .replace(/\n/g, ' ')
    .replace(/\r/g, '')
    .replace(/\t/g, ' ');
};

const escapedEnhanced = jsonEscape(enhancedQuestion);

console.log('原问题:', originalQuestion);
console.log('增强后:', enhancedQuestion);
console.log('是否增强:', originalQuestion !== enhancedQuestion);

return {
  json: {
    original_question: originalQuestion,
    enhanced_question: enhancedQuestion,
    escaped_enhanced_question: escapedEnhanced,
    was_enhanced: originalQuestion !== enhancedQuestion
  }
};
